 const toolbar=`<div class="pack-toolbar"><button class="btn primary" data-act="openTeach">▶ Teach Now</button><button class="btn ghost" data-act="notes">📚 Notes</button><button class="btn one-click-ppt" data-act="exportCompPptx">📊 ONE-CLICK PPT</button><button class="btn ghost" data-act="practice">✅ Practice</button><button class="btn ghost" data-act="printPack">🖨 Print Kit</button><button class="btn ghost" data-act="copyNotes">📋 Copy Notes</button><button class="btn ghost" data-act="shortsShare">📱 Shorts/Share</button><button class="btn ghost" data-act="favoriteCurrent">★ Favorite</button></div>`;
