 const head=`<div class="module-card accent"><div class="row"><div><span class="eyebrow">${esc(s.exam)} • ${esc(s.level)} • ${s.duration} MIN • ${esc(s.teachingMode||'Complete')}</span><h3>${esc(s.topic)}</h3><p>${esc(s.paperPost||'Paper/Post')} → ${esc(s.subject)} → ${esc(s.chapter)} • ${esc(s.language||'Hindi + English')} • ${esc(batch)}</p></div><div>${statusBadge(p)}</div></div><p><b>Teaching depth:</b> ${esc(p.levelNote)}</p>${p.officialVerified?'<p class="safe-banner">✅ Selected syllabus version official source से locked है. Teaching notes/PPT foundation material हैं; changing facts, authentic PYQ और year-specific claims source metadata के साथ ही दिखेंगे.</p>':(!p.verified?'<p class="safe-banner">🟡 Core teaching material ready है. लेकिन selected exam का exact current official syllabus अभी source-lock मांगता है.</p>':'')}</div>`;
