function offline(){const p=buildPack();show('Offline Class Mode','CLASSROOM / COACHING',`<div class="pack-toolbar"><button class="btn primary" data-act="openTeach">Digital Board Mode</button><button class="btn ghost" data-act="printPack">Print Class Kit</button><button class="btn ghost" data-act="notes">Printable Notes</button><button class="btn ghost" data-act="practice">Class Practice</button></div><div class="pack-sections"><div class="pack-section"><h4>Projector / Digital Board</h4><p>Full screen slides + whiteboard + answer reveal.</p></div><div class="pack-section"><h4>Normal Board Teaching</h4>${arrHtml(p.board,true)}</div><div class="pack-section"><h4>Student Handout</h4><p>Class notes + DPP + homework + revision sheet.</p></div><div class="pack-section"><h4>Attendance Link</h4><p>${window.SKY_STUDIO_CONFIG?.attendanceUrl?`<a class="btn ghost" href="${esc(window.SKY_STUDIO_CONFIG.attendanceUrl)}" target="_blank" rel="noopener">Open Attendance</a>`:'Set <code>attendanceUrl</code> in config.js to connect your existing attendance module without duplicating attendance data.'}</p></div><div class="pack-section"><h4>Low Internet</h4><p>Prepared topic bank, saved state and print material work without live content fetch. Current affairs freshness still requires verified import.</p></div></div>`) }
function youtube(){const p=buildPack(),s=p.selection;const title=`${s.topic} Complete Class | ${s.exam} ${s.level} | Sky Sir`,desc=`${s.topic} — ${s.exam}\n\nआज की class: ${p.mapping}\n${p.oneLine.join(' • ')}\n\nPractice + Homework included. Verify official exam notification/syllabus before relying on exam-specific claims.`;show('YouTube Class Mode','CREATOR PACK',`<div class="pack-sections"><div class="pack-section"><h4>Video Title</h4><p>${esc(title)}</p><button class="btn ghost" data-copy="${esc(title)}">Copy</button></div><div class="pack-section"><h4>Thumbnail Text</h4><p>${esc(s.topic.toUpperCase())} — ${esc(s.level.toUpperCase())}</p></div><div class="pack-section"><h4>Opening Hook</h4><p>${esc(p.trap||p.overview)}</p></div><div class="pack-section"><h4>Introduction</h4>${arrHtml(p.script.slice(0,2),true)}</div><div class="pack-section full"><h4>Full Teaching Script</h4>${arrHtml([...p.script,...p.teacher],true)}</div><div class="pack-section"><h4>Board Points</h4>${arrHtml(p.board)}</div><div class="pack-section"><h4>Examples / MCQ</h4>${arrHtml(p.examples)}${(p.mcq||[]).slice(0,2).map(q=>questionHtml(q)).join('')}</div><div class="pack-section"><h4>Ending Summary + Homework</h4>${arrHtml([...p.oneLine,...p.homework])}</div><div class="pack-section full"><h4>Description</h4><div class="clean-copy">${esc(desc)}</div></div><div class="pack-section"><h4>Keywords</h4><p>${esc([s.exam,s.subject,s.topic,'exam preparation','Sky Sir'].join(', '))}</p></div><div class="pack-section"><h4>Chapter Markers</h4>${arrHtml(['00:00 Hook','00:30 Concept','05:00 Examples','10:00 Exam Questions','End: Revision + Homework'])}</div><div class="pack-section"><h4>Short-video Points</h4>${arrHtml([p.trap,...p.oneLine].slice(0,4))}</div></div>`) }
