function slidesView(){currentPack=buildPack();makeTeachSlides();show('PPT / Slide Generator','14-STEP SLIDE STRUCTURE',`<div class="pack-toolbar"><button class="btn primary" data-act="openTeach">Open Full Screen</button><button class="btn ghost" data-act="exportCompPptx">Download PPTX</button></div><div class="module-grid">${teachSlides.map((s,i)=>`<div class="module-card"><span class="eyebrow">SLIDE ${i+1}</span><h4>${esc(s.t)}</h4><p>${esc(s.b||s.q||(s.items||[]).slice(0,2).join(' • '))}</p></div>`).join('')}</div><p class="safe-banner">PPT content comes from the same master topic pack; no separate duplicate content record is created.</p>`) }
function notesView(){const p=buildPack();show('Notes Generator','5 NOTE FORMATS',`<div class="mode-tabs"><button class="mode-tab active" data-note="full">Full Notes</button><button class="mode-tab" data-note="class">Class Notes</button><button class="mode-tab" data-note="one">One Page</button><button class="mode-tab" data-note="last">Last Minute</button><button class="mode-tab" data-note="pocket">Pocket Notes</button></div><div id="noteOutput" class="clean-copy">${esc(noteText('full',p))}</div><div class="pack-toolbar"><button class="btn primary" data-act="copyCurrentNote">Copy</button><button class="btn ghost" data-act="printPack">A4 Print Kit</button></div>`) }
function noteText(type,p=currentPack||buildPack()){const s=p.selection;const head=`${s.exam} | ${s.subject} | ${s.topic}\nLevel: ${s.level}\n`;if(type==='class')return `${head}\nCLASS NOTES\n${p.shortNotes.join('\n')}\n\nBOARD POINTS\n${p.board.join('\n')}\n\nHOMEWORK\n${p.homework.join('\n')}`;if(type==='one')return `${head}\nONE PAGE REVISION\n${[...p.oneLine,...p.formula,...p.facts,...p.mistakes.map(x=>'Avoid: '+x)].join('\n')}`;if(type==='last')return `${head}\nLAST MINUTE NOTES\n${[...p.oneLine,...p.formula,...p.tricks].slice(0,15).join('\n')}`;if(type==='pocket')return `${s.topic} — POCKET NOTES\n${[...p.oneLine,...p.formula,...p.facts].slice(0,10).join('\n')}`;return `${head}\nTOPIC OVERVIEW\n${p.overview}\n\nTHEORY\n${p.theory.join('\n')}\n\nFACTS\n${p.facts.join('\n')}\n\nFORMULA / METHOD\n${p.formula.join('\n')}\n\nEXAMPLES\n${p.examples.join('\n')}\n\nCOMMON MISTAKES\n${p.mistakes.join('\n')}\n\nREVISION\n${p.oneLine.join('\n')}`}
function copyNotes(){const p=buildPack();show('Copy-Paste Notes Mode','CLEAN TEXT',`<p class="muted-line">No unnecessary decorative symbols. Suitable for WhatsApp, Telegram, Word and Notes apps.</p><div id="cleanNotes" class="clean-copy">${esc(noteText('class',p))}</div><button class="btn primary" data-act="copyClean">Copy Clean Notes</button>`) }
function currentStudio(){const ca=state.currentAffairs||{},fresh=ca.date===iso()&&ca.status==='CURRENT'&&ca.lastVerified;show('Current Affairs Studio','FRESH-DATA WORKFLOW',`<div class="safe-banner">${fresh?'✅ Today’s pack is source-verified.':'⚠ No verified CURRENT pack for today. Old/current-unverified items will not be silently presented as current.'}</div><div class="pack-toolbar"><a class="btn ghost" href="https://pib.gov.in/" target="_blank" rel="noopener">PIB</a><a class="btn ghost" href="https://www.rbi.org.in/Scripts/BS_PressReleaseDisplay.aspx" target="_blank" rel="noopener">RBI</a><a class="btn ghost" href="https://www.isro.gov.in/" target="_blank" rel="noopener">ISRO</a><a class="btn ghost" href="https://www.mea.gov.in/" target="_blank" rel="noopener">MEA</a></div><p class="muted-line">Official/high-authority source देखकर Event → Important Point → Exam Relevance → Question → MCQ format में import/verify करें.</p><div class="ca-controls"><select id="caPeriod"><option>Daily</option><option>Weekly</option><option>Monthly</option></select><select id="caScope"><option>All</option><option>Exam-wise</option><option>State-wise</option><option>National</option><option>International</option><option>Economy</option><option>Science</option><option>Sports</option><option>Awards</option><option>Appointments</option><option>Schemes</option><option>Important Days</option></select><input id="caDate" type="date" value="${esc(ca.date||iso())}"><button class="btn ghost" data-act="caImport">Import / Verify</button></div><div id="caResults">${renderCaItems('All','Daily',ca.date||iso())}</div>`) }
function renderCaItems(scope='All',period='Daily',date=state.currentAffairs?.date||iso()){const ca=state.currentAffairs||{},base=new Date((date||iso())+'T00:00:00'),items=ca.items||[];const inPeriod=x=>{const ds=x.date||ca.date;if(!ds)return period!=='Daily';const d=new Date(ds+'T00:00:00'),delta=Math.floor((base-d)/86400000);if(period==='Daily')return ds===date;if(period==='Weekly')return delta>=0&&delta<7;if(period==='Monthly')return d.getFullYear()===base.getFullYear()&&d.getMonth()===base.getMonth();return true};const filtered=items.filter(x=>inPeriod(x)&&(scope==='All'||String(x.category||x.scope||'').toLowerCase().includes(scope.toLowerCase())||scope==='Exam-wise'&&(!x.category||x.exam)||scope==='State-wise'&&x.state));return filtered.length?filtered.map((x,i)=>`<div class="module-card"><span class="eyebrow">${esc(x.category||'CURRENT AFFAIRS')} • ${esc(x.date||ca.date||'')}</span><h4>${esc(x.event||x.question||'Item '+(i+1))}</h4><p><b>Important Point:</b> ${esc(x.point||x.answer||'')}</p><p><b>Exam Question:</b> ${esc(x.examQuestion||x.question||'')}</p><p><b>MCQ:</b> ${esc(x.mcq||'')}</p><small>${esc(x.source||ca.note||'Source required')}</small></div>`).join(''):'<div class="empty-state"><b>No matching verified current-affairs items.</b><span>Import / verify source-controlled items. The software will not fabricate news.</span></div>'}
function current100(){const n=Number(state.caCount||25),fresh=state.currentAffairs?.date===iso()&&state.currentAffairs?.status==='CURRENT'&&state.currentAffairs?.lastVerified,items=fresh?(state.currentAffairs?.items||[]).filter(x=>x.verified===true&&String(x.source||'').trim()).slice(0,n):[];show(`${n} Current Affairs Study Set`,'DAILY STUDY SET',`<div class="pack-toolbar">${[10,25,50,100].map(x=>`<button class="btn ${x===n?'primary':'ghost'}" data-ca-count="${x}">${x}</button>`).join('')}</div>${items.length?items.map((x,i)=>`<div class="question-card"><h4>${i+1}. ${esc(x.question||x.event||'Question')}</h4><div class="answer-box"><b>Answer:</b> ${esc(x.answer||x.point||'')}<br><b>Explanation:</b> ${esc(x.explanation||'')}<br><b>Exam relevance:</b> ${esc(x.relevance||'')}</div></div>`).join(''):`<div class="empty-state"><b>0 verified items available for ${esc(state.currentAffairs?.date||iso())}.</b><span>Requested ${n}. Import verified current affairs first; no fake set will be generated.</span></div>`}`) }
function vocab(){const n=Number(state.vocabCount||25),words=[...(state.customVocab||[]),...(D.vocabSeed||[])].slice(0,n);show('Daily Word Meaning','COMPETITIVE VOCABULARY',`<div class="pack-toolbar">${[10,25,50].map(x=>`<button class="btn ${x===n?'primary':'ghost'}" data-vocab-count="${x}">${x} Words</button>`).join('')}</div>${words.length<n?`<p class="safe-banner">Requested ${n}; bank currently has ${words.length}. Add/import more words instead of duplicating fake entries.</p>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Word</th><th>Pronunciation</th><th>Hindi</th><th>English</th><th>Synonym</th><th>Antonym</th><th>Example</th><th>Exam-style</th></tr></thead><tbody>${words.map((w,i)=>`<tr><td>${i+1}</td><td><b>${esc(w[0])}</b></td><td>${esc(w[1])}</td><td>${esc(w[2])}</td><td>${esc(w[3])}</td><td>${esc(w[4])}</td><td>${esc(w[5])}</td><td>${esc(w[6])}</td><td>Choose the closest meaning of “${esc(w[0])}”.</td></tr>`).join('')}</tbody></table></div>`) }
function pyq(){show('PYQ Center','SOURCE-LOCKED PREVIOUS YEAR QUESTIONS',`<div class="test-controls"><input id="pyqYear" placeholder="Year"><select id="pyqDifficulty"><option value="">All Difficulty</option><option>Easy</option><option>Medium</option><option>Hard</option><option>Very Hard</option></select><input id="pyqSearch" placeholder="Exam / subject / topic / question"><button class="btn ghost" data-act="admin">Add Verified PYQ</button></div><div id="pyqResults">${renderPyqResults()}</div>`) }
function renderPyqResults(){const year=($('#pyqYear')?.value||'').trim(),diff=$('#pyqDifficulty')?.value||'',term=($('#pyqSearch')?.value||'').trim().toLowerCase();const all=(state.pyqs||[]).filter(q=>(!year||String(q.year||'')===year)&&(!diff||q.difficulty===diff)&&(!term||JSON.stringify(q).toLowerCase().includes(term)));return all.length?all.map(q=>questionHtml(q,`PYQ ${q.exam||''} ${q.year||''}`)).join(''):'<div class="empty-state"><b>No matching authentic PYQ.</b><span>Only questions with source/paper reference can be labeled PYQ.</span></div>'}
function questionBank(){show('Central Question Bank','REUSABLE QUESTIONS',`<div class="test-controls"><select id="qbType"><option>All Types</option><option>MCQ</option><option>One Liner</option><option>Assertion</option><option>Statement based</option><option>Match</option><option>Numerical</option><option>Reasoning</option><option>Language</option></select><select id="qbDifficulty"><option>All Difficulty</option><option>Easy</option><option>Medium</option><option>Hard</option><option>Very Hard</option></select><input id="qbSearch" placeholder="Search question/topic"><button class="btn ghost" data-act="admin">Add Question</button></div><div id="qbResults">${renderQuestionBank()}</div>`) }
function renderQuestionBank(){const type=$('#qbType')?.value||'All Types',diff=$('#qbDifficulty')?.value||'All Difficulty',term=($('#qbSearch')?.value||'').trim().toLowerCase();const all=allStoredQuestions().filter(q=>(type==='All Types'||(q.type||'MCQ')===type)&&(diff==='All Difficulty'||q.difficulty===diff)&&(!term||JSON.stringify(q).toLowerCase().includes(term)));return all.length?all.map(q=>questionHtml(q,q.isPyq?'PYQ':'Question Bank')).join(''):'<div class="empty-state"><b>No matching stored questions.</b><span>Change filter or add verified/original questions in Admin.</span></div>'}
function testGenerator(){show('Test Generator','ONE-CLICK TEST',`<div class="test-controls"><select id="testCount">${[10,25,50,100].map(x=>`<option>${x}</option>`).join('')}</select><select id="testMode"><option>Topic Test</option><option>Chapter Test</option><option>Subject Test</option><option>Full Exam Mock</option></select><select id="testDifficulty"><option>Mixed</option><option>Easy</option><option>Medium</option><option>Hard</option></select><button class="btn primary" data-act="runGeneratedTest">Generate & Start</button></div><p class="safe-banner">Generator samples only from stored question bank. If the requested count is larger than the bank, it returns the available verified questions instead of inventing items.</p>`) }
function mock(){const mp=state.mockPatterns?.[state.selection.exam]||{questions:100,marks:100,negative:0,time:120,sections:'Configure from official pattern'};show('Mock Test Mode','EXAM PATTERN CONFIG',`<div class="form-grid"><label>Total Questions<input id="mockQ" type="number" value="${mp.questions}"></label><label>Total Marks<input id="mockMarks" type="number" value="${mp.marks}"></label><label>Negative / wrong<input id="mockNeg" type="number" step="0.01" value="${mp.negative}"></label><label>Time (minutes)<input id="mockTime" type="number" value="${mp.time}"></label><label>Sections<input id="mockSections" value="${esc(mp.sections)}"></label><button class="btn ghost" data-act="saveMock">Save Pattern</button></div><button class="btn primary" data-act="runMock">▶ Start Mock from Question Bank</button><p class="safe-banner">Official pattern must be verified before saving. Default is only a configurable template, not an official claim.</p>`) }
function practiceMode(items,opts={}){const qs=items?.length?items:relevantQuestions();if(!qs.length)return toast('No stored questions for this topic');practice={items:qs,i:0,correct:0,wrong:0,skipped:0,answered:false,start:Date.now(),negative:Number(opts.negative)||0,marksPerQuestion:Number(opts.marksPerQuestion)||1,weak:[],mode:opts.mode||'Practice'};$('#practiceTitle').textContent=practice.mode;renderPractice();$('#practiceDialog').showModal()}
function renderPractice(){const q=practice.items[practice.i],b=$('#practiceBody');if(!q){const attempted=practice.correct+practice.wrong,unattempted=Math.max(0,practice.items.length-attempted),accuracy=attempted?Math.round(practice.correct/attempted*100):0,score=(practice.correct*practice.marksPerQuestion)-(practice.wrong*practice.negative),elapsed=Math.max(1,Math.round((Date.now()-practice.start)/60000));state.tests.unshift({exam:state.selection.exam,topic:state.selection.topic,date:iso(),score,correct:practice.correct,wrong:practice.wrong,unattempted,accuracy});save();cloudInsert('teaching_attempts',{course_key:state.selection.exam,attempt_type:practice.mode,score,max_score:practice.items.length*practice.marksPerQuestion,accuracy,weak_topics:[...new Set(practice.weak)],result_json:{correct:practice.correct,incorrect:practice.wrong,unattempted,topic:state.selection.topic}});b.innerHTML=`<div class="module-card accent"><h3>${esc(practice.mode)} Complete</h3><div class="progress-strip"><div class="progress-tile"><b>${score.toFixed(2)}</b><span>Score</span></div><div class="progress-tile"><b>${accuracy}%</b><span>Accuracy</span></div><div class="progress-tile"><b>${practice.correct}</b><span>Correct</span></div><div class="progress-tile"><b>${practice.wrong}</b><span>Incorrect</span></div><div class="progress-tile"><b>${unattempted}</b><span>Unattempted</span></div><div class="progress-tile"><b>${elapsed}m</b><span>Time Used</span></div></div><div class="answer-box"><b>Topic Weakness:</b> ${practice.weak.length?esc([...new Set(practice.weak)].join(', ')):'No wrong-topic signal in this attempt.'}</div></div>`;return}const opts=q.options||q.o||[];b.innerHTML=`<div class="question-card"><span class="eyebrow">QUESTION ${practice.i+1} / ${practice.items.length}</span><h3>${esc(q.q)}</h3>${opts.map((o,i)=>`<button class="option-btn" data-practice-answer="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}<div class="pack-toolbar"><button class="btn ghost" data-act="skipPractice">Skip / Unattempted</button></div><div id="practiceExplain"></div></div>`}
function skipPractice(){if(practice.answered)return;practice.skipped++;practice.i++;practice.answered=false;renderPractice()}
function answerPractice(i){if(practice.answered)return;practice.answered=true;const q=practice.items[practice.i],a=q.answer??q.a,ok=i===a;if(ok)practice.correct++;else{practice.wrong++;practice.weak.push(q.topic||q.concept||state.selection.topic);}$$('[data-practice-answer]').forEach((b,j)=>{if(j===a)b.classList.add('correct');else if(j===i)b.classList.add('wrong')});$('#practiceExplain').innerHTML=`<div class="answer-box"><b>${ok?'✅ Correct':'❌ Incorrect'}</b><br><b>Correct Answer:</b> ${esc((q.options||q.o||[])[a])}<br><b>Why correct:</b> ${esc(q.explanation||q.e||'')}<br><b>Concept:</b> ${esc(q.concept||state.selection.topic)}${q.shortcut?`<br><b>Safe shortcut:</b> ${esc(q.shortcut)}`:''}${q.whyWrong?`<br><b>Why others wrong:</b><ul>${q.whyWrong.map((x,j)=>x?`<li>${String.fromCharCode(65+j)}: ${esc(x)}</li>`:'').join('')}</ul>`:''}<br><button class="btn primary" data-act="nextPractice">Next →</button></div>`}
function marathon(){const p=buildPack();show('Marathon Class Mode','HIGH-YIELD SEQUENCE',`<div class="pack-toolbar"><button class="btn primary" data-act="openTeach">Start Marathon Slides</button></div><div class="pack-sections"><div class="pack-section"><h4>Important Concepts</h4>${arrHtml([...p.basic,...p.theory])}</div><div class="pack-section"><h4>Important Facts</h4>${arrHtml(p.facts)}</div><div class="pack-section"><h4>PYQ / Pattern</h4><p>${esc(p.pattern)}</p></div><div class="pack-section"><h4>Expected Questions</h4>${p.expected.slice(0,5).map(q=>questionHtml(q)).join('')}</div><div class="pack-section"><h4>Tricks</h4>${arrHtml(p.tricks)}</div><div class="pack-section"><h4>Rapid Revision</h4>${arrHtml(p.oneLine)}</div></div>`) }
function revision(){const p=buildPack();show('Revision Class Mode','RAPID REVISION',`<div class="pack-toolbar">${[15,30,60].map(x=>`<button class="btn ghost" data-revision-min="${x}">${x} Minute</button>`).join('')}<button class="btn ghost" data-revision-min="chapter">Full Chapter</button><button class="btn ghost" data-revision-min="subject">Full Subject</button></div><div id="revisionOutput" class="pack-sections"><div class="pack-section"><h4>One-Line Recall</h4>${arrHtml(p.oneLine)}</div><div class="pack-section"><h4>Formula / Facts</h4>${arrHtml([...p.formula,...p.facts])}</div><div class="pack-section"><h4>Mistakes</h4>${arrHtml(p.mistakes)}</div><div class="pack-section"><h4>Quick Practice</h4>${arrHtml(p.dpp)}</div></div>`) }
function doubt(){show('Doubt Teaching Mode','SAFE INSTANT LOOKUP',`<div class="pack-toolbar"><input id="doubtInput" placeholder="Question / Topic search"><button class="btn primary" data-act="searchDoubt">Search</button></div><div id="doubtResult" class="empty-state"><b>Search a topic or stored question.</b><span>If data is unavailable, the system will say so instead of fabricating an answer.</span></div>`) }
function searchDoubt(){const term=($('#doubtInput')?.value||'').trim().toLowerCase(),found=Object.entries(D.verifiedTopics||{}).find(([k,v])=>k.toLowerCase().includes(term)||JSON.stringify(v).toLowerCase().includes(term));const q=(state.questions||[]).find(q=>q.q.toLowerCase().includes(term));const out=$('#doubtResult');if(found){const [name,r]=found;out.className='module-card accent';out.innerHTML=`<h3>${esc(name)}</h3><p><b>Concept:</b> ${esc(r.overview)}</p><p><b>Explanation:</b> ${esc((r.theory||[]).join(' '))}</p><p><b>Example:</b> ${esc((r.examples||[])[0]||'No stored example')}</p><p><b>Related:</b> ${esc((r.dpp||[]).slice(0,3).join(' • '))}</p>`}else if(q){out.className='module-card accent';out.innerHTML=questionHtml(q)}else{out.className='empty-state';out.innerHTML='<b>Verified answer not available.</b><span>Add the topic/question to Content Bank or Personal Content; no fake answer generated.</span>'}}
function subjectModes(){const modes={'Mathematics':['Question → Given → Formula → Step 1 → Step 2 → Final Answer → Shortcut → Common Mistake','Use structured solution template; shortcut only when concept-safe.'],'Reasoning':['Concept → Pattern → Method → Solved Examples → Practice → Speed Trick → Timer','Timer practice after accuracy.'],'Polity':['Article/Provision → Constitution → Amendment/Body → Powers → Comparison → Cases if relevant → PYQ → One-liners','Article/case/date must be source-verified.'],'History':['Timeline → Event → Cause → Result → Person → Date → Exam Facts → MCQ → Memory','Date/person source lock.'],'Geography':['Concept → Map → Location → Physical Features → Facts → Comparison → Map Questions → PYQ','Map-based teaching encouraged.'],'Science':['Basic Concept → Definition → Diagram → Daily-life Example → Scientific Fact → Formula → MCQ','Textbook/source verification.'],'Hindi':['व्याकरण → नियम → उदाहरण → अपवाद → प्रश्न','संधि, समास, पर्याय, विलोम, मुहावरे, वाक्य शुद्धि, गद्यांश.'],'English':['Grammar → Vocabulary → Error Detection → Cloze/Reading → PYQ','Context + rule + exception.'],'Child Development & Pedagogy':['Theory → Psychologist → Principle → Example → Classroom Application → RTE → Inclusive → Assessment → PYQ','Confusing options explicitly compare.']};show('Subject Teaching Modes','SPECIALIZED TEACHING FLOW',`<div class="subject-mode-grid">${Object.entries(modes).map(([k,v])=>`<div class="subject-mode"><h4>${esc(k)}</h4><p>${esc(v[0])}</p><small>${esc(v[1])}</small></div>`).join('')}</div>`) }
function stateGk(){const rec=state.stateGK||{};show('State-Specific GK','STATE FILTER',`<div class="pack-toolbar"><select id="stateSelect"><option>Uttar Pradesh</option><option>Bihar</option><option>Madhya Pradesh</option><option>Rajasthan</option><option>Uttarakhand</option><option>Other State</option></select><select id="stateCat"><option>History</option><option>Geography</option><option>Economy</option><option>Culture</option><option>Rivers</option><option>Districts</option><option>Schemes</option><option>Current Affairs</option></select><button class="btn primary" data-act="loadStateGk">Open</button></div><div id="stateGkOut" class="empty-state"><b>Choose state/category.</b><span>Verified state-specific bank is separate from generic GS. Current affairs require freshness metadata.</span></div>`) }
function loadStateGk(){const st=$('#stateSelect')?.value||'Uttar Pradesh',cat=$('#stateCat')?.value||'History',items=state.stateGK?.[st]?.[cat]||[];const out=$('#stateGkOut');if(!out)return;if(!items.length){out.className='empty-state';out.innerHTML=`<b>No verified ${esc(st)} ${esc(cat)} content.</b><span>Admin can import source-verified state GK. Current Affairs category must include date/freshness metadata.</span>`}else{out.className='module-grid';out.innerHTML=items.map(x=>`<div class="module-card"><h4>${esc(x.title||cat)}</h4><p>${esc(x.point||x.content||'')}</p><small>${esc(x.source||'Source required')}</small></div>`).join('')}}
function batches(){show('Batch Management','ONLINE / OFFLINE COACHING',`<div class="pack-toolbar"><button class="btn primary" data-act="newBatch">+ New Batch</button></div><p class="safe-banner">Batch stores schedule/teacher/student references only. Teaching content remains in central Content Bank and is not copied per batch.</p><div>${(state.batches||[]).map((b,i)=>`<div class="batch-card"><b>${esc(b.name)}</b><p>${esc(b.exam)} • ${esc(b.time)} • Start ${esc(b.start)} • ${esc(b.status||'Active')}</p><small>${esc((b.subjects||[]).join(', '))} • Teacher: ${esc(b.teacher||'')} • Students: ${Number(b.students||0)}</small><div class="pack-toolbar"><button class="btn ghost" data-batch-start="${i}">Set as Today’s Class</button><button class="btn ghost" data-batch-toggle="${i}">${b.active===false?'Activate':'Pause'}</button></div></div>`).join('')||'<div class="empty-state"><b>No batches yet.</b><span>Create online/offline coaching batch.</span></div>'}</div>`) }
function newBatch(){show('Create Batch','BATCH MANAGEMENT',`<div class="form-grid"><input id="bName" placeholder="Batch Name"><select id="bExam">${allExams().map(x=>`<option>${esc(x.name)}</option>`).join('')}</select><input id="bStart" type="date" value="${iso()}"><input id="bTime" type="time" value="18:00"><input id="bTeacher" placeholder="Teacher" value="Sky Sir"><input id="bSubjects" placeholder="Subjects comma separated"><input id="bStudents" type="number" min="0" value="0" placeholder="Student count"><select id="bStatus"><option>Active</option><option>Upcoming</option><option>Paused</option><option>Completed</option></select></div><button class="btn primary" data-act="saveBatch">Save Batch</button>`) }
function today(){const idx=state.selection.batch!==''?Number(state.selection.batch):0,b=state.batches?.[idx],queue=(state.scheduleQueue||[]).filter(x=>x.date===iso()&&x.status!=='DONE');if(!b&&!queue.length)return show("Today's Class",'DAILY BATCH VIEW',`<div class="module-card accent"><h3>${esc(state.selection.exam)}</h3><p>${esc(state.selection.subject)} → ${esc(state.selection.topic)} • ${state.selection.duration} min</p><p>Previous: ${esc(state.classHistory?.[0]?.topic||'—')} • Next: ${esc(nextTopicLabel())}</p><button class="btn primary" data-act="startComplete">Start Teaching</button></div><p class="muted-line">Create a batch/course plan to bind Today’s Class to a schedule.</p>`);let cards='';if(b)cards+=`<div class="module-card accent"><span class="eyebrow">${esc(b.name)} • ${esc(b.status||'Active')}</span><h3>${esc(b.exam)}</h3><p>${esc(b.time)} • ${esc(state.selection.subject)} → ${esc(state.selection.topic)} • ${state.selection.duration} min</p><p>Previous: ${esc(state.classHistory?.[0]?.topic||'—')} • Next: ${esc(nextTopicLabel())}</p><button class="btn primary" data-act="startComplete">Start Teaching</button></div>`;cards+=queue.map(q=>`<div class="module-card"><span class="eyebrow">${esc(q.status)}</span><h4>${esc(q.topic)}</h4><p>${esc(q.exam)} • ${esc(q.subject)} • ${esc(q.reason||'Scheduled')}</p></div>`).join('');show("Today's Class",'DAILY BATCH VIEW',cards) }
function nextTopicLabel(){const topics=planTopics(),i=topics.findIndex(x=>x.subject===state.selection.subject&&x.chapter===state.selection.chapter&&x.topic===state.selection.topic);return topics[i+1]?.topic||'Revision / next planned topic'}
function planner(){const id=state.selection.exam,p=state.planners[id]||{start:iso(),target:'',days:60,daysPerWeek:6,minutesPerDay:120,revisionEvery:7,testEvery:7};show('Course Planner','SYLLABUS → TOPICS → TARGET DAYS',`<div class="form-grid"><label>Start Date<input id="planStart" type="date" value="${p.start}"></label><label>Target Date<input id="planTarget" type="date" value="${p.target||''}"></label><label>Target Teaching Days<input id="planDays" type="number" min="1" value="${p.days}"></label><label>Days / Week<input id="planDaysWeek" type="number" min="1" max="7" value="${p.daysPerWeek||6}"></label><label>Minutes / Day<input id="planMinutes" type="number" min="15" step="15" value="${p.minutesPerDay||120}"></label><label>Revision every N days<input id="planRevision" type="number" min="1" value="${p.revisionEvery||7}"></label><label>Test every N days<input id="planTest" type="number" min="1" value="${p.testEvery||7}"></label></div><button class="btn primary" data-act="savePlanner">Build / Update Plan</button><div id="planOut">${renderPlan(p)}</div>`) }
function planTopics(){return subjectsFor(state.selection.exam).flatMap(sub=>chaptersFor(sub).flatMap(ch=>topicsFor(sub,ch).map(t=>({subject:sub,chapter:ch,topic:t}))))}
function renderPlan(p){const ts=planTopics(),days=Math.max(1,Number(p.days)||60),per=Math.max(1,Math.ceil(ts.length/days)),rev=Math.max(1,Number(p.revisionEvery)||7),test=Math.max(1,Number(p.testEvery)||7),start=p.start?new Date(p.start+'T00:00:00'):new Date();let topicIndex=0;const cards=[];for(let i=0;i<Math.min(days,60);i++){const day=i+1,date=new Date(start);date.setDate(start.getDate()+i);let title='',sub='';if(day%test===0){title='Weekly / Cycle Test';sub='MCQ + weak-topic analysis + PYQ/PYQ-style'}else if(day%rev===0){title='Fast Revision + Weak Topic Recovery';sub='Current Affairs + revision + practice'}else{const chunk=ts.slice(topicIndex,topicIndex+per);topicIndex+=chunk.length;title=chunk.length?chunk.map(x=>x.topic).join(' + '):'Full Revision / Mock / Buffer';sub=chunk.map(x=>x.subject).filter((v,j,a)=>a.indexOf(v)===j).join(', ');if(chunk.length)sub+=(sub?' • ':'')+'Daily Current Affairs + Fast Revision + Practice Set'}cards.push(`<div class="module-card"><span class="eyebrow">DAY ${day} • ${date.toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}</span><h4>${esc(title)}</h4><small>${esc(sub)}</small></div>`)}return `<div class="module-grid">${cards.join('')}</div>${days>60?'<p class="muted-line">Showing first 60 planned days. Full target-day settings are retained.</p>':''}` }
function completion(){const all=planTopics(),subjects=[...new Set(all.map(x=>x.subject))],chapters=[...new Set(all.map(x=>x.subject+'|'+x.chapter))],done=(state.completed||[]).filter(x=>x.startsWith(state.selection.exam+'|')).length,tests=(state.tests||[]).filter(x=>x.exam===state.selection.exam).length,rev=(state.revisionPending||[]).filter(x=>x.startsWith(state.selection.exam+'|')).length,pct=Math.round(done/Math.max(1,all.length)*100),plan=state.planners[state.selection.exam],expectedTests=plan?Math.floor((Number(plan.days)||0)/Math.max(1,Number(plan.testEvery)||7)):0;show('Syllabus Completion','PROGRESS TRACKER',`<div class="progress-strip"><div class="progress-tile"><b>${subjects.length}</b><span>Subjects</span></div><div class="progress-tile"><b>${chapters.length}</b><span>Chapters</span></div><div class="progress-tile"><b>${all.length}</b><span>Total Topics</span></div><div class="progress-tile"><b>${done}</b><span>Completed</span></div><div class="progress-tile"><b>${Math.max(0,all.length-done)}</b><span>Remaining</span></div><div class="progress-tile"><b>${rev}</b><span>Revision Pending</span></div><div class="progress-tile"><b>${tests}</b><span>Tests Completed</span></div><div class="progress-tile"><b>${Math.max(0,expectedTests-tests)}</b><span>Tests Pending</span></div><div class="progress-tile"><b>${pct}%</b><span>Completion</span></div></div><div class="progress-line"><span style="width:${pct}%"></span></div>`) }
function studentPack(){const p=buildPack();show('Student Material Pack','ONE TOPIC → STUDENT PACK',`<div class="pack-sections"><div class="pack-section"><h4>Notes</h4>${arrHtml(p.shortNotes)}</div><div class="pack-section"><h4>Class Notes</h4>${arrHtml(p.board)}</div><div class="pack-section"><h4>DPP</h4>${arrHtml(p.dpp)}</div><div class="pack-section"><h4>Homework</h4>${arrHtml(p.homework)}</div><div class="pack-section"><h4>Quiz</h4>${(p.mcq||[]).slice(0,5).map(q=>questionHtml(q)).join('')}</div><div class="pack-section"><h4>Revision Sheet</h4>${arrHtml([...p.oneLine,...p.formula])}</div></div><button class="btn primary" data-act="printPack">Print A4 Kit</button>`) }
function personal(){const k=topicKey(),r=state.personal[k]||{note:'',trick:'',question:'',example:'',explanation:''};show('Teacher Personal Content','REUSABLE MY CONTENT',`<p>${esc(k)}</p><div class="form-grid"><textarea id="pcNote" placeholder="Notes">${esc(r.note)}</textarea><textarea id="pcTrick" placeholder="Safe trick">${esc(r.trick)}</textarea><textarea id="pcQuestion" placeholder="Question">${esc(r.question)}</textarea><textarea id="pcExample" placeholder="Example">${esc(r.example)}</textarea><textarea id="pcExplain" placeholder="Explanation">${esc(r.explanation)}</textarea><textarea id="pcCore" placeholder="Verified core overview (optional)">${esc(r.core?.overview||'')}</textarea></div><button class="btn primary" data-act="savePersonal">Save & Reuse</button>`) }
function contentBank(){const keys=Object.keys(D.verifiedTopics||{}),personalKeys=Object.keys(state.personal||{});show('Reusable Content Bank','CENTRAL CONTENT ARCHITECTURE',`<p class="safe-banner">Hierarchy: Exam layer → Subject → Unit/Chapter → Topic → Material. Common core topic is stored once; exam layer stores only exam-specific practice/mapping.</p><div class="module-grid">${keys.map(k=>{const r=D.verifiedTopics[k];return `<div class="module-card"><span class="status-lock ${/^(VERIFIED|CURRENT|UPDATED|TEACHER VERIFIED)/i.test(r.status||'')?'ok':'review'}">${esc(r.status||'NEEDS REVIEW')}</span><h4>${esc(k)}</h4><p>${esc(r.subject||'')}</p><button class="btn ghost" data-bank-topic="${esc(k)}">Open</button></div>`}).join('')}${personalKeys.map(k=>`<div class="module-card"><span class="status-lock review">MY CONTENT</span><h4>${esc(k.split('|').pop())}</h4><p>${esc(k)}</p></div>`).join('')}</div>`) }
function materialHub(){
 const subs=Object.keys(D.subjectMap||{}),exams=allExams().length,topics=Object.keys(D.verifiedTopics||{}).length,c=D.contentCoverageC1||{};
 const cards=subs.map(sub=>{const ch=D.subjectMap[sub]||{},count=Object.values(ch).reduce((n,a)=>n+(a?.length||0),0);return `<details class="syllabus-subject hub-subject"><summary><b>${esc(sub)}</b><span>${count} topics • ${Object.keys(ch).length} chapters</span></summary>${Object.entries(ch).map(([chapter,ts])=>`<div class="syllabus-chapter"><h4>${esc(chapter)}</h4><div class="syllabus-topic-grid">${(ts||[]).map(t=>`<button class="module-card hub-topic" data-search-topic="${esc(t)}" data-search-subject="${esc(sub)}" data-search-chapter="${esc(chapter)}"><b>${esc(t)}</b><small>Complete Class • Notes • PPT • Test</small><span class="tag">OPEN</span></button>`).join('')}</div></div>`).join('')}</details>`}).join('');
 show('Complete Study Material Hub','C1 • A–Z CONTENT BANK',`<div class="progress-strip"><div class="progress-tile"><b>${exams}</b><span>Exam options</span></div><div class="progress-tile"><b>${subs.length}</b><span>Subjects</span></div><div class="progress-tile"><b>${topics}</b><span>Topic packs</span></div><div class="progress-tile"><b>${c.mcqs||0}</b><span>Built-in MCQs</span></div><div class="progress-tile"><b>${c.dppTasks||0}</b><span>DPP tasks</span></div><div class="progress-tile"><b>${c.pptReady||0}</b><span>PPT-ready topics</span></div></div><p class="safe-banner">✅ Static syllabus material is preloaded and normalized for teaching. ${c.dynamicSourceGated||0} date-sensitive/current topics stay source-gated so stale or invented current facts are never shown as current.</p><div class="syllabus-tree hub-tree">${cards}</div>`,'Common core once • exam-specific layer separate • storage efficient');
}
function examLayerView(){const l=examLayer();show('Exam-Specific Layer','CORE ONCE • EXAM LAYER SEPARATE',`<div class="module-card accent"><h3>${esc(state.selection.topic)} — Core Concept</h3><p>${esc(findRecord()?.overview||generic(state.selection.subject).overview)}</p></div><div class="module-grid">${['SSC CGL','IBPS PO','UPPSC','BPSC TRE'].map(ex=>`<div class="module-card"><h4>${ex}</h4><p>${esc(state.examLayers?.[`${ex}|${state.selection.topic}`]?.note||'Exam-specific authentic mapping/questions not locked yet. Add in Admin; core concept is reused without duplication.')}</p></div>`).join('')}</div>`) }

function officialStatusClass(cfg){return /OFFICIAL VERIFIED/i.test(cfg?.status||'')?'verified':(/SOURCE|POST|LOCK|SCHEME/i.test(cfg?.status||'')?'review':'neutral')}
function renderOfficialHub(category=''){const cat=$('#officialCategoryGrid'),grid=$('#officialExamGrid'),title=$('#officialPanelTitle');if(!cat||!grid)return;cat.innerHTML=(O.categoryCards||[]).map(c=>`<button class="official-category-card tone-${esc(c.tone)}" data-official-category="${esc(c.key)}"><span class="official-icon">${c.icon}</span><b>${esc(c.title)}</b><small>${esc(c.desc)}</small><em>OPEN HUB →</em></button>`).join('');const names=category?(D.categories?.[category]||[]):allExams().map(x=>x.name);if(title)title.textContent=category||'All Competitive Exams';grid.innerHTML=names.map(name=>{const cfg=O.exams?.[name],st=cfg?.status||'SOURCE LOCK REQUIRED',cls=officialStatusClass(cfg),posts=Object.keys(cfg?.posts||{}).length;return `<button class="official-exam-card ${cls}" data-official-exam="${esc(name)}"><span class="exam-card-status">${esc(st)}</span><b>${esc(name)}</b><small>${cfg?esc(cfg.version||'Official source profile'): 'Exact current official syllabus must be locked before teaching as official.'}</small><div><span>${posts?posts+' paper/post option'+(posts>1?'s':''):'Post/paper source required'}</span><strong>OPEN →</strong></div></button>`}).join('')}
function openOfficialHub(){renderOfficialHub();document.getElementById('officialHubZone')?.scrollIntoView({behavior:'smooth',block:'start'})}
function startFromSelection(){syncSelection();const mode=state.selection.teachingMode||'Complete';if(mode==='Online')return online();if(mode==='Offline')return offline();if(mode==='YouTube')return youtube();if(mode==='Live')return liveScript();return completeView()}
function favoriteCurrent(){const key=`topic|${state.selection.exam}|${topicKey()}`,i=(state.favorites||[]).findIndex(x=>x.key===key);if(i>=0){state.favorites.splice(i,1);toast('Removed from Favorites')}else{state.favorites.push({key,type:'Topic',label:state.selection.topic,exam:state.selection.exam,subject:state.selection.subject,chapter:state.selection.chapter,topic:state.selection.topic,createdAt:new Date().toISOString()});toast('Added to Favorites')}save()}
function favorites(){const f=state.favorites||[];show('Favorites','QUICK REUSE',f.length?`<div class="module-grid">${f.map((x,i)=>`<div class="module-card"><span class="eyebrow">${esc(x.type||'Saved')}</span><h4>${esc(x.label||x.topic||'Favorite')}</h4><p>${esc(x.exam||'')} • ${esc(x.subject||'')}</p><div class="pack-toolbar">${x.topic?`<button class="btn ghost" data-fav-open="${i}">Open</button>`:''}<button class="btn ghost" data-fav-remove="${i}">Remove</button></div></div>`).join('')}</div>`:'<div class="empty-state"><b>No favorites yet.</b><span>Favorite any selected topic for one-tap reuse.</span></div>')}
function globalSearch(){show('Global Competition Search','EXAM • TOPIC • QUESTION • PYQ • VOCABULARY • FACT',`<div class="pack-toolbar"><input id="globalSearchInput" placeholder="Search exam, topic, question, PYQ, word or fact"><button class="btn primary" data-act="runGlobalSearch">Search</button></div><div id="globalSearchResults" class="empty-state"><b>Type a keyword.</b><span>Search runs only when you click Search.</span></div>`)}
function runGlobalSearch(){const t=($('#globalSearchInput')?.value||'').trim().toLowerCase(),out=$('#globalSearchResults');if(!t){out.innerHTML='<b>Enter a keyword.</b>';return}const res=[];allExams().forEach(e=>{if(e.name.toLowerCase().includes(t))res.push({type:'Exam',label:e.name,meta:e.cat})});Object.entries(D.verifiedTopics||{}).forEach(([k,v])=>{if((k+' '+JSON.stringify(v)).toLowerCase().includes(t))res.push({type:'Topic',label:k,meta:`${v.subject||''} • ${v.chapter||''}`,topic:k,subject:v.subject,chapter:v.chapter})});[...(state.questions||[]),...(state.pyqs||[])].forEach(q=>{if(JSON.stringify(q).toLowerCase().includes(t))res.push({type:q.isPyq?'PYQ':'Question',label:q.q,meta:`${q.subject||''} • ${q.difficulty||''}`})});[...(state.customVocab||[]),...(D.vocabSeed||[])].forEach(w=>{if(w.join(' ').toLowerCase().includes(t))res.push({type:'Vocabulary',label:w[0],meta:`${w[2]} • ${w[3]}`})});(state.currentAffairs?.items||[]).forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(t))res.push({type:'Current Affairs',label:x.event||x.question||'Item',meta:x.category||''})});out.className='module-grid';out.innerHTML=res.length?res.slice(0,80).map((r,i)=>`<div class="module-card"><span class="eyebrow">${esc(r.type)}</span><h4>${esc(r.label)}</h4><p>${esc(r.meta||'')}</p>${r.topic?`<button class="btn ghost" data-search-topic="${esc(r.topic)}" data-search-subject="${esc(r.subject||'')}" data-search-chapter="${esc(r.chapter||'')}">Open Topic</button>`:''}</div>`).join(''):'<div class="empty-state"><b>No stored match.</b><span>Doubt mode will not invent missing data.</span></div>'}
function masterTopic(){const k=topicKey(),r=findRecord()||{},vers=state.topicVersions[k]||[];show('Master Topic & Version Control','ONE CORE → ALL OUTPUTS',`<p class="safe-banner">Editing here updates the canonical teacher-owned topic override used by slides, notes, script, video pack, shorts, practice and print. Built-in verified seed is not destructively changed.</p><div class="form-grid"><label>Overview<textarea id="mtOverview" rows="4">${esc(r.overview||'')}</textarea></label><label>Theory (one point per line)<textarea id="mtTheory" rows="7">${esc((r.theory||[]).join('\n'))}</textarea></label><label>Class Notes (one per line)<textarea id="mtNotes" rows="6">${esc((r.notes||r.shortNotes||[]).join('\n'))}</textarea></label><label>Safe Tricks (one per line)<textarea id="mtTricks" rows="5">${esc((r.tricks||[]).join('\n'))}</textarea></label><label>Examples (one per line)<textarea id="mtExamples" rows="5">${esc((r.examples||[]).join('\n'))}</textarea></label><label>Change Note<input id="mtChange" placeholder="What changed?"></label></div><button class="btn primary" data-act="saveMasterTopic">UPDATE ALL RELATED OUTPUTS</button><h4>Version History</h4>${vers.length?vers.slice().reverse().map(v=>`<div class="module-card"><b>v${v.version}</b> • ${esc(v.updatedAt)}<p>${esc(v.changeNote||'Update')}</p></div>`).join(''):'<p class="muted-line">No teacher-owned versions yet.</p>'}`)}
async function saveMasterTopic(){const k=topicKey(),old=clone(state.personal[k]?.core||findRecord()||{}),versions=state.topicVersions[k]||(state.topicVersions[k]=[]),version=(versions.at(-1)?.version||0)+1;versions.push({version,updatedAt:new Date().toISOString(),changeNote:$('#mtChange')?.value||'Update all outputs',snapshot:old});state.personal[k]??={};state.personal[k].core={...old,subject:state.selection.subject,chapter:state.selection.chapter,overview:$('#mtOverview').value.trim(),theory:$('#mtTheory').value.split('\n').map(x=>x.trim()).filter(Boolean),notes:$('#mtNotes').value.split('\n').map(x=>x.trim()).filter(Boolean),tricks:$('#mtTricks').value.split('\n').map(x=>x.trim()).filter(Boolean),examples:$('#mtExamples').value.split('\n').map(x=>x.trim()).filter(Boolean),status:'TEACHER VERIFIED',version,updatedAt:new Date().toISOString()};save();if(window.SKY_DB?.configured()){try{const topic={id:state.personal[k].core.cloudId||crypto.randomUUID(),title:state.selection.topic,subject:state.selection.subject,chapter:state.selection.chapter,...state.personal[k].core};state.personal[k].core.cloudId=topic.id;await SKY_DB.saveTopic(topic);await SKY_DB.saveTopicVersion(topic,$('#mtChange')?.value||'Update all outputs');save()}catch(e){toast('Local saved; cloud version: '+e.message)}}toast('Master topic updated — all outputs now use this version');masterTopic()}
function shortsShare(){const p=buildPack(),s=p.selection,shorts=[{name:'30-sec Concept',text:`${s.topic}: ${p.oneLine[0]||p.overview}`},{name:'60-sec Concept',text:`Hook: ${p.trap}\nConcept: ${p.overview}\nRevision: ${p.oneLine.join(' ')}`},{name:'Exam Question Short',text:(p.expected[0]?.q||p.dpp[0]||'Verified question required.')},{name:'Common Mistake Short',text:p.mistakes[0]||'No verified mistake stored.'},{name:'Quick Trick Short',text:p.tricks[0]||'No safe shortcut stored; teach concept method.'},{name:'Revision Short',text:p.oneLine.join(' • ')}];show('Shorts + Share Center','REUSE ONE MASTER TOPIC',`<div class="module-grid">${shorts.map((x,i)=>`<div class="module-card"><span class="eyebrow">${esc(x.name)}</span><p>${esc(x.text)}</p><div class="pack-toolbar"><button class="btn ghost" data-short-copy="${i}">Copy</button><button class="btn ghost" data-short-share="${i}">Share</button></div></div>`).join('')}</div><p class="safe-banner">Native share opens the device share sheet. Direct platform upload is not claimed without the platform’s official API/login.</p>`);window.__skyShorts=shorts}
async function shareText(text,title='Sky Sir Competition Studio'){try{if(navigator.share)await navigator.share({title,text});else{await navigator.clipboard.writeText(text);toast('Share API unavailable — copied instead')}}catch(e){if(e.name!=='AbortError')toast('Share unavailable: '+e.message)}}
function classContinuity(){const queued=state.scheduleQueue||[];show('Class Continuity','COMPLETE • CONTINUE • RESCHEDULE',`<div class="pack-toolbar"><button class="btn primary" data-act="finishClass">✅ Complete Current</button><button class="btn ghost" data-act="continueTomorrow">↪ Continue Tomorrow</button><button class="btn ghost" data-act="rescheduleClass">⏭ Class Not Taken → Reschedule</button></div><p class="safe-banner">A missed class never marks the topic complete. Reschedule/continue keeps the topic in the queue.</p><div class="module-grid">${queued.length?queued.map(q=>`<div class="module-card"><span class="eyebrow">${esc(q.date)} • ${esc(q.status)}</span><h4>${esc(q.topic)}</h4><p>${esc(q.exam)} • ${esc(q.subject)} • ${esc(q.reason||'')}</p></div>`).join(''):'<div class="empty-state"><b>No pending carry-forward classes.</b></div>'}</div>`)}
function tomorrowIso(){const d=new Date();d.setDate(d.getDate()+1);return d.toISOString().slice(0,10)}
function continueTomorrow(){syncSelection();state.scheduleQueue.push({date:tomorrowIso(),status:'CONTINUE',reason:'Topic needs more time',...clone(state.selection)});save();if($('#teachDialog')?.open)$('#teachDialog').close();toast('Topic carried to tomorrow — not marked complete');classContinuity()}
function rescheduleClass(){syncSelection();state.scheduleQueue.push({date:tomorrowIso(),status:'RESCHEDULED',reason:'Class not taken; future plan must shift',...clone(state.selection)});save();toast('Class rescheduled; topic not skipped');classContinuity()}
function weeklyFinal(){const p=state.planners[state.selection.exam]||{revisionEvery:7,testEvery:7};show('Weekly + Final Revision Engine','REVISION CYCLE',`<div class="module-grid"><div class="module-card"><span class="eyebrow">EVERY ${Number(p.revisionEvery)||7} TEACHING DAYS</span><h4>Weekly Revision</h4>${arrHtml(['Fast revision','MCQ test','Weak-topic revision','Previous questions / PYQ-style practice'])}</div><div class="module-card"><span class="eyebrow">CHAPTER COMPLETE</span><h4>Chapter Cycle</h4>${arrHtml(['Chapter Revision','Chapter Test','Analysis','Next Chapter'],true)}</div><div class="module-card"><span class="eyebrow">FULL SYLLABUS COMPLETE</span><h4>Final Cycle</h4>${arrHtml(['Full Revision Plan','Subject Mock Tests','Full Exam Mock','Final Exam Practice'],true)}</div></div><div class="pack-toolbar"><button class="btn primary" data-act="revision">Open Revision</button><button class="btn ghost" data-act="testGen">Generate Test</button><button class="btn ghost" data-act="mock">Open Mock</button></div>`)}
function accuracyCenter(){const ca=state.currentAffairs||{},fresh=ca.date===iso()&&ca.status==='CURRENT'&&ca.lastVerified,layer=examLayer(),pyq=(state.pyqs||[]).filter(q=>q.source).length;show('Source & Accuracy Center','VERIFY BEFORE CLAIM',`<div class="progress-strip"><div class="progress-tile"><b>${findRecord()?'CORE':'REVIEW'}</b><span>Topic Core</span></div><div class="progress-tile"><b>${esc(layer.status||'REVIEW')}</b><span>Exam Layer</span></div><div class="progress-tile"><b>${fresh?'CURRENT':'STALE/REVIEW'}</b><span>Current Affairs</span></div><div class="progress-tile"><b>${pyq}</b><span>Source-locked PYQ</span></div></div><div class="pack-sections"><div class="pack-section"><h4>Source Priority</h4>${arrHtml(['Official notification','Official syllabus','Official exam pattern','Official corrigendum','Authentic PYQ','Government/official source','Standard academic source'],true)}</div><div class="pack-section"><h4>Status Rules</h4>${arrHtml(['VERIFIED / CURRENT only with adequate verification','STALE when date-sensitive pack is old','NEEDS REVIEW for incomplete source metadata','SUPERSEDED when official update replaces old version'])}</div><div class="pack-section full"><h4>Non-negotiable Safety</h4><p>Never invent facts, dates, laws, articles, official patterns, current affairs or PYQ provenance. Practice questions without paper/source remain PYQ-style/original practice.</p></div></div>`)}
function remoteView(){show('Teacher Remote','PRIVATE PHONE CONTROL',`<div class="module-card accent"><h3>Phone Remote Foundation</h3><p>Open the separate remote page on your phone. With Supabase configured, pairing is restricted by database RLS to the same authenticated owner/account.</p><a class="btn primary" href="remote.html" target="_blank" rel="noopener">Open Teacher Remote</a></div><p class="safe-banner">Teacher notes remain private on the phone. Do not put passwords/session tokens in URLs.</p>`)}

function admin(){show('Competition Studio Admin','ADD / EDIT WITHOUT CODE CHANGE',`<div class="mode-tabs"><button class="mode-tab active" data-admin-tab="exam">Exam</button><button class="mode-tab" data-admin-tab="topic">Subject/Topic</button><button class="mode-tab" data-admin-tab="question">Question/PYQ</button><button class="mode-tab" data-admin-tab="current">Current Affairs</button><button class="mode-tab" data-admin-tab="vocab">Vocabulary</button><button class="mode-tab" data-admin-tab="layer">Exam Layer</button><button class="mode-tab" data-admin-tab="source">Source</button><button class="mode-tab" data-admin-tab="mock">Mock Pattern</button></div><div id="adminOut">${adminPanel('exam')}</div>`) }
function adminPanel(t){if(t==='exam')return `<div class="admin-card"><h4>Add Exam</h4><div class="form-grid"><input id="adExam" placeholder="Exam name"><input id="adCategory" placeholder="Category"><input id="adSubjects" placeholder="Subjects comma separated"><input id="adExamSource" placeholder="Official syllabus/notification URL or reference"><input id="adExamVersion" placeholder="Syllabus version"></div><button class="btn primary" data-act="adminAddExam">Add Exam</button></div>`;if(t==='topic')return `<div class="admin-card"><h4>Add Subject / Chapter / Topic</h4><div class="form-grid"><input id="adSubject" placeholder="Subject"><input id="adChapter" placeholder="Chapter"><input id="adTopic" placeholder="Topic"></div><button class="btn primary" data-act="adminAddTopic">Add Topic</button><p class="muted-line">Then use Master Topic / Personal Content to add verified explanation, notes and examples.</p></div>`;if(t==='question')return `<div class="admin-card"><h4>Add Question / Verified PYQ</h4><div class="form-grid"><input id="adQ" placeholder="Question"><input id="adOpts" placeholder="Options separated by |"><input id="adAnswer" type="number" min="1" placeholder="Correct option no."><input id="adExplain" placeholder="Why correct / explanation"><input id="adConcept" placeholder="Underlying concept"><input id="adWhyWrong" placeholder="Why options wrong separated by |"><input id="adShortcut" placeholder="Safe shortcut (optional)"><select id="adIsPyq"><option value="no">Question Bank</option><option value="yes">Authentic PYQ</option></select><input id="adYear" placeholder="PYQ year"><input id="adSource" placeholder="Source / paper reference"><select id="adDiff"><option>Easy</option><option>Medium</option><option>Hard</option><option>Very Hard</option></select></div><button class="btn primary" data-act="adminAddQuestion">Save</button></div>`;if(t==='current')return `<div class="admin-card"><h4>Import Verified Current Affairs JSON</h4><textarea id="adCA" rows="10" placeholder='[{"event":"...","point":"...","question":"...","answer":"...","source":"...","verified":true}]'></textarea><div class="form-grid"><input id="adCADate" type="date" value="${iso()}"><input id="adCASource" placeholder="Verification note/source"><select id="adCAStatus"><option>NEEDS REVIEW</option><option>CURRENT</option></select></div><button class="btn primary" data-act="adminSaveCA">Save Pack</button></div>`;if(t==='vocab')return `<div class="admin-card"><h4>Add Vocabulary</h4><div class="form-grid"><input id="adWord" placeholder="Word"><input id="adPron" placeholder="Pronunciation"><input id="adHindi" placeholder="Hindi meaning"><input id="adEnglish" placeholder="English meaning"><input id="adSyn" placeholder="Synonym"><input id="adAnt" placeholder="Antonym"><input id="adExample" placeholder="Example"><input id="adVocabSource" placeholder="Source note"></div><button class="btn primary" data-act="adminAddVocab">Save Word</button></div>`;if(t==='layer')return `<div class="admin-card"><h4>Exam-Specific Layer</h4><p>${esc(state.selection.exam)} • ${esc(state.selection.topic)}</p><textarea id="adLayer" rows="8" placeholder="Verified exam-specific pattern, source notes, question emphasis"></textarea><input id="adLayerSource" placeholder="Official/source reference"><button class="btn primary" data-act="adminSaveLayer">Save Layer</button></div>`;if(t==='source')return `<div class="admin-card"><h4>Register Source / Verification</h4><div class="form-grid"><input id="adSourceTitle" placeholder="Source title"><input id="adSourceType" placeholder="Official Notification / Syllabus / Book"><input id="adSourceUrl" placeholder="URL/reference"><input id="adSourceVersion" placeholder="Version/date"><select id="adSourceStatus"><option>VERIFIED</option><option>NEEDS REVIEW</option><option>SUPERSEDED</option></select></div><button class="btn primary" data-act="adminSaveSource">Save Source</button></div>`;return `<div class="admin-card"><h4>Mock Pattern — ${esc(state.selection.exam)}</h4><div class="form-grid"><input id="mockQ" type="number" placeholder="Total questions"><input id="mockMarks" type="number" placeholder="Total marks"><input id="mockNeg" type="number" step="0.01" placeholder="Negative marking"><input id="mockTime" type="number" placeholder="Time minutes"><input id="mockSections" placeholder="Sections"><input id="mockSource" placeholder="Official pattern source/reference"></div><button class="btn primary" data-act="saveMock">Save Verified Pattern</button></div>`}
function coverage(){const items=['Primary goal','Exam architecture','Exact one-click flow','Complete teaching pack','One master topic','Zero to advanced','Online mode','Offline mode','YouTube mode','Live script','PPT engine','Notes engine','Copy-paste mode','Current Affairs','Daily CA set','Vocabulary','PYQ center','Question bank','Test generator','Mock engine','Answer explanation','Practice','Marathon','Revision','Doubt','Maths mode','Reasoning mode','Polity mode','History mode','Geography mode','Science mode','Hindi mode','English mode','CDP mode','State GK','Batch management',"Today's class",'Course planner','Syllabus completion','Daily mixed competition plan','Student material pack','Print class kit','Online class kit','Start complete class','Teacher personal content','Central content bank','Admin control','Content/source safety','Free-first architecture','Supabase architecture','Silent until click','Offline support','Responsive','Premium 3D UI','Navigation','Print/PDF','Search & favorites','Version control','Class progress/continuity','Weekly/final revision','YouTube/Shorts reuse','Share center','Security','Performance','Final test matrix','Two-pass audit','Final delivery','Final report','Strict do-not rules','Final success criteria'];show('Master Command Coverage','IMPLEMENTATION MAP',`<div class="module-grid">${items.map((x,i)=>`<div class="module-card good"><span class="status-lock ok">FLOW PRESENT</span><h4>#${i+1} ${esc(x)}</h4><p>${['Content engine/workflow exists','Reusable shared engine','Safety/source rules enforced'][i%3]}</p></div>`).join('')}</div><p class="safe-banner">Flow present does not mean every exam’s official syllabus/PYQ/current affairs dataset is pre-populated. Source-controlled content remains separate from software correctness.</p>`) }
function printPack(){const p=currentPack||buildPack(),w=window.open('','_blank');if(!w)return toast('Pop-up blocked');const q=(p.mcq||[]).slice(0,10);w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Print Class Kit</title><style>@page{size:A4;margin:12mm}body{font:12pt/1.45 Arial,"Noto Sans Devanagari",sans-serif;color:#111}h1{font-size:20pt}h2{font-size:15pt;border-bottom:1px solid #bbb;padding-bottom:5px}.page{break-after:page}.box{border:1px solid #bbb;padding:10px;margin:8px 0}.small{font-size:9pt;color:#555}ol,ul{padding-left:22px}</style></head><body><div class="page"><h1>Teacher Lesson Sheet — ${esc(p.selection.topic)}</h1><p>${esc(p.selection.exam)} • ${esc(p.selection.subject)} • ${esc(p.selection.level)} • ${p.selection.duration} min</p><h2>Teaching Sequence</h2>${arrHtml(p.teacher,true)}<h2>Board Work</h2>${arrHtml(p.board,true)}<h2>Common Mistakes / Trap</h2>${arrHtml(p.mistakes)}<p>${esc(p.trap)}</p></div><div class="page"><h1>Student Notes</h1><h2>${esc(p.selection.topic)}</h2>${arrHtml(p.shortNotes)}<h2>Revision</h2>${arrHtml(p.oneLine)}</div><div class="page"><h1>Practice Sheet / DPP</h1>${arrHtml(p.dpp,true)}${q.map((x,i)=>`<div class="box"><b>${i+1}. ${esc(x.q)}</b><br>${(x.o||x.options||[]).map((o,j)=>`${String.fromCharCode(65+j)}. ${esc(o)}`).join('<br>')}</div>`).join('')}</div><div class="page"><h1>Homework</h1>${arrHtml(p.homework,true)}<h2>Answer Key</h2>${q.map((x,i)=>`<p>${i+1}. ${esc((x.o||x.options||[])[x.a??x.answer])} — ${esc(x.e||x.explanation||'')}</p>`).join('')}<p class="small">Authentic PYQ label appears only when source metadata is present.</p></div><script>onload=()=>print()<\/script></body></html>`);w.document.close()}
async function exportPptx(){if(!window.PptxGenJS)return toast('PPTX engine unavailable');syncSelection();currentPack=buildPack();makeTeachSlides();const ppt=new PptxGenJS();ppt.layout='LAYOUT_WIDE';ppt.author='Sky Sir Classes';teachSlides.forEach((s,i)=>{const sl=ppt.addSlide();sl.background={color:'07162C'};sl.addText(s.t||'',{x:.65,y:.55,w:11.9,h:.7,fontSize:27,bold:true,color:'FFFFFF'});let text=s.b||s.q||(s.items||[]).map(x=>'• '+x).join('\n');if(s.options?.length)text+='\n\n'+s.options.map((o,j)=>`${String.fromCharCode(65+j)}. ${o}`).join('\n');sl.addText(text||'',{x:.8,y:1.55,w:11.5,h:4.9,fontSize:20,color:'DCEAFF',breakLine:true,margin:.05,valign:'mid'});sl.addText(`${currentPack.selection.exam} • ${currentPack.selection.topic} • Sky Sir`,{x:.8,y:7,w:11.5,h:.25,fontSize:9,color:'7FB9F5',align:'right'})});await ppt.writeFile({fileName:`${state.selection.exam}-${state.selection.topic}-Sky-Sir.pptx`})}
function completeClass(){syncSelection();const k=`${state.selection.exam}|${state.selection.subject}|${state.selection.chapter}|${state.selection.topic}`;if(!state.completed.includes(k))state.completed.push(k);state.classHistory.unshift({date:iso(),status:'COMPLETE',...clone(state.selection)});state.scheduleQueue=(state.scheduleQueue||[]).filter(q=>!(q.exam===state.selection.exam&&q.subject===state.selection.subject&&q.topic===state.selection.topic&&q.status!=='DONE'));const sameExam=state.classHistory.filter(x=>x.exam===state.selection.exam&&x.status==='COMPLETE').length;if(sameExam%7===0&&!state.revisionPending.includes(k))state.revisionPending.push(k);save();if($('#teachDialog')?.open)$('#teachDialog').close();toast('Class marked complete');updateHeader();completion()}
function copy(t){navigator.clipboard?.writeText(t).then(()=>toast('Copied')).catch(()=>toast('Clipboard unavailable'))}
function startTimer(){clearInterval(countdown);let n=30,e=$('#teachCountdown');e.hidden=false;const p=()=>e.textContent=`00:${String(n).padStart(2,'0')}`;p();countdown=setInterval(()=>{n--;p();if(n<=0){clearInterval(countdown);e.textContent='TIME!';setTimeout(()=>e.hidden=true,1500)}},1000)}
const canvas=$('#compWhiteboard'),ctx=canvas.getContext('2d');let drawing=false;function resizeBoard(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.setTransform(d,0,0,d,0,0);ctx.strokeStyle='#ffd166';ctx.lineWidth=4;ctx.lineCap='round'}function pt(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}canvas.addEventListener('pointerdown',e=>{if(!canvas.classList.contains('active'))return;drawing=true;const p=pt(e);ctx.beginPath();ctx.moveTo(p.x,p.y)});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=pt(e);ctx.lineTo(p.x,p.y);ctx.stroke()});addEventListener('pointerup',()=>drawing=false);
async function cloudSync(){if(!window.SKY_DB?.configured())return toast('Cloud not configured — local/offline mode active');try{const u=await SKY_DB.user();if(!u)return toast('Login Required / पहले main Teaching Studio में cloud login करें');const rows=await SKY_DB.select('teaching_settings');const existing=rows[0]?.settings_json||{};const remote=existing.competitionStudio||null;const localTime=Date.parse(state.updatedAt||0),remoteTime=Date.parse(remote?.updatedAt||0);if(remote&&remoteTime>localTime){state={...clone(defaults),...remote};localStorage.setItem(LS,JSON.stringify(state));hydrate();toast('Newer Competition Studio state restored from cloud')}else{await SKY_DB.upsert('teaching_settings',{settings_json:{...existing,competitionStudio:state},updated_at:new Date().toISOString()},'owner_id');toast('Competition Studio synced to cloud')}$('#cloudChip').textContent='☁ Synced'}catch(e){toast('Cloud Sync: '+e.message)}}
function savePlanner(){state.planners[state.selection.exam]={start:$('#planStart').value,target:$('#planTarget').value,days:Number($('#planDays').value)||60,daysPerWeek:Number($('#planDaysWeek').value)||6,minutesPerDay:Number($('#planMinutes').value)||120,revisionEvery:Number($('#planRevision').value)||7,testEvery:Number($('#planTest').value)||7};save();$('#planOut').innerHTML=renderPlan(state.planners[state.selection.exam]);cloudSave('teaching_course_plans',{course_key:state.selection.exam,start_date:state.planners[state.selection.exam].start||null,target_date:state.planners[state.selection.exam].target||null,minutes_per_class:state.planners[state.selection.exam].minutesPerDay,class_days:Array.from({length:Math.max(1,Math.min(7,state.planners[state.selection.exam].daysPerWeek))},(_,i)=>i+1),revision_every:state.planners[state.selection.exam].revisionEvery,test_every:state.planners[state.selection.exam].testEvery,plan_json:state.planners[state.selection.exam]},'owner_id,course_key');toast('Course plan saved')}
function saveBatch(){const b={name:$('#bName').value||'New Batch',exam:$('#bExam').value,start:$('#bStart').value,time:$('#bTime').value,teacher:$('#bTeacher').value,subjects:$('#bSubjects').value.split(',').map(x=>x.trim()).filter(Boolean),students:Number($('#bStudents').value)||0,status:$('#bStatus').value,active:$('#bStatus').value!=='Paused'&&$('#bStatus').value!=='Completed'};state.batches.unshift(b);save();refreshBatchSelect();cloudSave('competition_batches',{batch_name:b.name,exam_name:b.exam,start_date:b.start||null,class_time:b.time||null,subject_keys:b.subjects||[],student_count:b.students||0,active:b.active,schedule_json:{teacher:b.teacher,status:b.status}},'owner_id,batch_name');batches()}
function savePersonal(){const k=topicKey();state.personal[k]={note:$('#pcNote').value,trick:$('#pcTrick').value,question:$('#pcQuestion').value,example:$('#pcExample').value,explanation:$('#pcExplain').value};if($('#pcCore').value.trim())state.personal[k].core={subject:state.selection.subject,chapter:state.selection.chapter,overview:$('#pcCore').value.trim(),status:'TEACHER VERIFIED',notes:[$('#pcNote').value],tricks:[$('#pcTrick').value],examples:[$('#pcExample').value],theory:[$('#pcExplain').value]};save();toast('Personal content saved');personal()}
function adminAddExam(){const name=$('#adExam').value.trim();if(!name)return;const category=$('#adCategory').value||'Custom',subjects=$('#adSubjects').value.split(',').map(x=>x.trim()).filter(Boolean),source=$('#adExamSource')?.value.trim()||'',version=$('#adExamVersion')?.value.trim()||'';if(!(state.customExams||[]).some(x=>x.name===name))state.customExams.push({name,category});state.customSubjects[name]=subjects;save();hydrate();toast('Exam added without code change');cloudSave('competition_exam_catalog',{exam_name:name,category,official_source_url:source||null,syllabus_version:version||null,source_status:source?'VERIFIED':'NEEDS REVIEW',last_verified_at:source?iso():null,metadata_json:{subjects}},'owner_id,exam_name')}
function adminAddTopic(){const s=$('#adSubject').value.trim(),c=$('#adChapter').value.trim(),t=$('#adTopic').value.trim();if(!s||!c||!t)return;state.customTopics[s]??={};state.customTopics[s][c]??=[];if(!state.customTopics[s][c].includes(t))state.customTopics[s][c].push(t);save();toast('Topic added')}
function adminAddQuestion(){const opts=$('#adOpts').value.split('|').map(x=>x.trim()).filter(Boolean),isPyq=$('#adIsPyq').value==='yes',source=$('#adSource').value.trim(),year=$('#adYear').value.trim();if(isPyq&&(!source||!year))return toast('Authentic PYQ requires year + source/paper reference');const why=($('#adWhyWrong')?.value||'').split('|').map(x=>x.trim());while(why.length<opts.length)why.push('');const q={id:crypto.randomUUID(),exam:state.selection.exam,subject:state.selection.subject,chapter:state.selection.chapter,topic:state.selection.topic,type:'MCQ',difficulty:$('#adDiff').value,q:$('#adQ').value,options:opts,answer:Math.max(0,Number($('#adAnswer').value)-1),explanation:$('#adExplain').value,concept:$('#adConcept')?.value||state.selection.topic,whyWrong:why,shortcut:$('#adShortcut')?.value||'',isPyq,year,source,verified:!!(isPyq?source&&year:true)};(isPyq?state.pyqs:state.questions).push(q);save();toast(isPyq?'Verified PYQ saved':'Question saved');if(isPyq){cloudInsert('competition_pyq_sources',{exam_name:q.exam,year:Number(q.year),subject:q.subject,topic:q.topic,question_json:q,source_label:q.source,verified_at:new Date().toISOString()});cloudInsert('teaching_question_bank',{question_type:q.type,source_type:'PYQ',question_json:q,difficulty:q.difficulty,exam_tag:q.exam,source_ref:q.source,verified:true})}else cloudInsert('teaching_question_bank',{question_type:q.type,source_type:'ORIGINAL',question_json:q,difficulty:q.difficulty,exam_tag:q.exam,verified:true})}
function adminSaveCA(){let items;try{items=JSON.parse($('#adCA').value)}catch{return toast('Invalid JSON')};if(!Array.isArray(items))return toast('JSON must be an array');const status=$('#adCAStatus').value,note=$('#adCASource').value.trim(),date=$('#adCADate').value;if(status==='CURRENT'){if(!note)return toast('CURRENT status requires verification source/note');const bad=items.find(x=>!x||x.verified!==true||!String(x.source||'').trim());if(bad)return toast('CURRENT pack requires verified:true + source on every item');if(date!==iso())return toast('CURRENT pack date must be today; older pack should be STALE/NEEDS REVIEW')}state.currentAffairs={date,status,lastVerified:status==='CURRENT'?new Date().toISOString():'',note,items};save();toast('Current Affairs pack saved');if(window.SKY_DB?.configured())SKY_DB.saveCurrentAffairs(state.currentAffairs).catch(e=>toast('Cloud CA: '+e.message))}
function adminSaveLayer(){const note=$('#adLayer').value.trim(),source=$('#adLayerSource')?.value.trim()||'';state.examLayers[`${state.selection.exam}|${state.selection.topic}`]={status:source?'VERIFIED BY ADMIN':'NEEDS REVIEW',note,source,updatedAt:new Date().toISOString()};save();toast(source?'Exam layer saved with source':'Layer saved as NEEDS REVIEW');cloudSave('competition_exam_layers',{exam_name:state.selection.exam,topic_key:topicKey(),layer_json:{note},source_refs:source?[source]:[],status:source?'VERIFIED':'NEEDS REVIEW'},'owner_id,exam_name,topic_key')}
function saveMock(){const source=$('#mockSource')?.value.trim()||'',obj={questions:Number($('#mockQ').value)||100,marks:Number($('#mockMarks').value)||100,negative:Number($('#mockNeg').value)||0,time:Number($('#mockTime').value)||120,sections:$('#mockSections').value||'',source,status:source?'VERIFIED':'NEEDS REVIEW'};state.mockPatterns[state.selection.exam]=obj;save();toast(source?'Mock pattern saved with source':'Pattern saved as NEEDS REVIEW');cloudSave('competition_mock_patterns',{exam_name:state.selection.exam,pattern_version:'current',total_questions:obj.questions,total_marks:obj.marks,negative_marking:obj.negative,time_minutes:obj.time,sections_json:{text:obj.sections},official_source_url:source||null,status:obj.status,last_verified_at:source?iso():null},'owner_id,exam_name,pattern_version')}
function runGeneratedTest(){const count=Number($('#testCount').value),mode=$('#testMode').value,diff=$('#testDifficulty').value;let qs=allStoredQuestions();if(mode==='Topic Test')qs=qs.filter(q=>q.topic===state.selection.topic);else if(mode==='Chapter Test')qs=qs.filter(q=>q.subject===state.selection.subject&&(q.chapter? q.chapter===state.selection.chapter:true));else if(mode==='Subject Test')qs=qs.filter(q=>q.subject===state.selection.subject);if(diff!=='Mixed')qs=qs.filter(q=>q.difficulty===diff);practiceMode(qs.slice(0,count),{mode})}
function runMock(){const mp=state.mockPatterns[state.selection.exam]||{questions:100,marks:100,negative:0,time:120};let qs=allStoredQuestions().filter(q=>{const subs=subjectsFor(state.selection.exam);return !q.subject||subs.includes(q.subject)}).slice(0,Number(mp.questions));const marksPer=Number(mp.marks||mp.questions)/Math.max(1,Number(mp.questions));practiceMode(qs,{negative:Number(mp.negative)||0,marksPerQuestion:marksPer,mode:`${state.selection.exam} Mock`})}

function adminAddVocab(){const w=$('#adWord')?.value.trim();if(!w)return toast('Word required');const row=[w,$('#adPron').value,$('#adHindi').value,$('#adEnglish').value,$('#adSyn').value,$('#adAnt').value,$('#adExample').value];state.customVocab=state.customVocab||[];if(![...(state.customVocab||[]),...(D.vocabSeed||[])].some(x=>x[0].toLowerCase()===w.toLowerCase()))state.customVocab.unshift(row);save();toast('Vocabulary saved');cloudSave('competition_vocab_bank',{word:w,pronunciation:row[1],hindi_meaning:row[2],english_meaning:row[3],synonym:row[4],antonym:row[5],example_text:row[6],source_note:$('#adVocabSource').value||''},'owner_id,word')}
function adminSaveSource(){const title=$('#adSourceTitle')?.value.trim();if(!title)return toast('Source title required');state.sourceRegistry.unshift({title,type:$('#adSourceType').value,url:$('#adSourceUrl').value,version:$('#adSourceVersion').value,status:$('#adSourceStatus').value,verifiedAt:new Date().toISOString()});save();toast('Source record saved')}

async function cloudSave(table,row,conflict){try{if(window.SKY_DB?.configured())await SKY_DB.upsert(table,row,conflict)}catch(e){toast('Cloud: '+e.message)}}
async function cloudInsert(table,row){try{if(!window.SKY_DB?.configured())return;const u=await SKY_DB.user();if(!u)return;const {error}=await SKY_DB.get().from(table).insert({...row,owner_id:u.id});if(error)throw error}catch(e){toast('Cloud: '+e.message)}}
function action(a){const m={back:backView,home:homeView,officialHub:openOfficialHub,syllabus:syllabusBrowser,focusSelector:()=>$('#selectorPanel').scrollIntoView({behavior:'smooth'}),startComplete:startFromSelection,complete:completeView,openTeach,online,onlineKit:online,offline,offlineKit:offline,youtube,youtubeKit:youtube,liveScript,slides:slidesView,notes:notesView,copyNotes,current:currentStudio,current100,vocab,pyq,questionBank,testGen:testGenerator,mock,practice:()=>practiceMode(),marathon,revision,doubt,subjectModes,stateGk,loadStateGk,batches,today,planner,completion,studentPack,personal,contentBank,materialHub,examLayer:examLayerView,masterTopic,shortsShare,search:globalSearch,favorites,favoriteCurrent,schedule:classContinuity,weeklyFinal,accuracy:accuracyCenter,remote:remoteView,admin,coverage,cloudSync,close:homeView,prevTeach:()=>{teachIndex=Math.max(0,teachIndex-1);revealed=false;renderTeach()},nextTeach:()=>{teachIndex=Math.min(teachSlides.length-1,teachIndex+1);revealed=false;renderTeach()},teachReveal:()=>{revealed=!revealed;renderTeach()},teachBoard:()=>canvas.classList.toggle('active'),teachTimer:startTimer,printPack,exportCompPptx:exportPptx,finishClass:completeClass,continueTomorrow,rescheduleClass,copyCurrentNote:()=>copy($('#noteOutput').textContent),copyClean:()=>copy($('#cleanNotes').textContent),searchDoubt,savePlanner,newBatch,saveBatch,savePersonal,saveMasterTopic,runGlobalSearch,adminAddExam,adminAddTopic,adminAddQuestion,adminSaveCA,adminSaveLayer,adminAddVocab,adminSaveSource,saveMock,runGeneratedTest,runMock,skipPractice,nextPractice:()=>{practice.i++;practice.answered=false;renderPractice()},caImport:admin};const restorable=new Set(['syllabus','complete','online','offline','youtube','liveScript','slides','notes','copyNotes','current','current100','vocab','pyq','questionBank','testGen','mock','marathon','revision','doubt','subjectModes','stateGk','batches','today','planner','completion','studentPack','personal','contentBank','materialHub','examLayer','masterTopic','shortsShare','search','favorites','schedule','weeklyFinal','accuracy','remote','admin']);if(restorable.has(a)){state.lastModule=a;save()}return m[a]?.()}
addEventListener('change',e=>{if(e.target.id==='examSelect'){state.selection.exam=e.target.value;state.selection.paperPost=postsFor(state.selection.exam)[0]||'';refreshPaperPost()}else if(e.target.id==='paperPostSelect'){state.selection.paperPost=e.target.value;refreshSubjects()}else if(e.target.id==='subjectSelect'){state.selection.subject=e.target.value;refreshChapters()}else if(e.target.id==='chapterSelect'){state.selection.chapter=e.target.value;refreshTopics()}else if(['topicSelect','levelSelect','durationSelect','batchSelect','languageSelect','teachingModeSelect'].includes(e.target.id))syncSelection();else if(['caScope','caPeriod','caDate'].includes(e.target.id)&&$('#caResults'))$('#caResults').innerHTML=renderCaItems($('#caScope').value,$('#caPeriod').value,$('#caDate').value);else if(['pyqYear','pyqDifficulty'].includes(e.target.id)&&$('#pyqResults'))$('#pyqResults').innerHTML=renderPyqResults();else if(['qbType','qbDifficulty'].includes(e.target.id)&&$('#qbResults'))$('#qbResults').innerHTML=renderQuestionBank()});
addEventListener('input',e=>{if(e.target.id==='pyqSearch'&&$('#pyqResults'))$('#pyqResults').innerHTML=renderPyqResults();else if(e.target.id==='qbSearch'&&$('#qbResults'))$('#qbResults').innerHTML=renderQuestionBank()});
addEventListener('click',e=>{const a=e.target.closest('[data-act]');if(a){action(a.dataset.act);return}const c=e.target.closest('[data-close]');if(c){document.getElementById(c.dataset.close)?.close();return}const pa=e.target.closest('[data-practice-answer]');if(pa){answerPractice(Number(pa.dataset.practiceAnswer));return}const nt=e.target.closest('[data-note]');if(nt){$$('[data-note]').forEach(x=>x.classList.toggle('active',x===nt));$('#noteOutput').textContent=noteText(nt.dataset.note,currentPack||buildPack());return}const ac=e.target.closest('[data-admin-tab]');if(ac){$$('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===ac));$('#adminOut').innerHTML=adminPanel(ac.dataset.adminTab);return}const cc=e.target.closest('[data-ca-count]');if(cc){state.caCount=Number(cc.dataset.caCount);save();current100();return}const vc=e.target.closest('[data-vocab-count]');if(vc){state.vocabCount=Number(vc.dataset.vocabCount);save();vocab();return}const cp=e.target.closest('[data-copy]');if(cp){copy(cp.dataset.copy);return}const bt=e.target.closest('[data-bank-topic]');if(bt){const name=bt.dataset.bankTopic,r=D.verifiedTopics[name];state.selection.subject=r.subject||state.selection.subject;state.selection.chapter=r.chapter||state.selection.chapter;state.selection.topic=name;save();hydrate();completeView();return}const bs=e.target.closest('[data-batch-start]');if(bs){state.selection.batch=bs.dataset.batchStart;const b=state.batches[Number(bs.dataset.batchStart)];state.selection.exam=b.exam;save();hydrate();today();return}const tog=e.target.closest('[data-batch-toggle]');if(tog){const b=state.batches[Number(tog.dataset.batchToggle)];b.active=b.active===false; b.status=b.active?'Active':'Paused';save();refreshBatchSelect();batches();return}const rm=e.target.closest('[data-revision-min]');if(rm){const val=rm.dataset.revisionMin;if(!isNaN(Number(val))){state.selection.duration=Number(val);save();hydrate()}toast(`Revision mode: ${val}`);return}const fo=e.target.closest('[data-fav-open]');if(fo){const x=state.favorites[Number(fo.dataset.favOpen)];if(x?.topic){state.selection.exam=x.exam||state.selection.exam;state.selection.subject=x.subject||state.selection.subject;state.selection.chapter=x.chapter||state.selection.chapter;state.selection.topic=x.topic;save();hydrate();completeView()}return}const fr=e.target.closest('[data-fav-remove]');if(fr){state.favorites.splice(Number(fr.dataset.favRemove),1);save();favorites();return}const st=e.target.closest('[data-search-topic]');if(st){state.selection.subject=st.dataset.searchSubject||state.selection.subject;state.selection.chapter=st.dataset.searchChapter||state.selection.chapter;state.selection.topic=st.dataset.searchTopic;save();hydrate();completeView();return}const sc=e.target.closest('[data-short-copy]');if(sc){copy(window.__skyShorts?.[Number(sc.dataset.shortCopy)]?.text||'');return}const ss=e.target.closest('[data-short-share]');if(ss){shareText(window.__skyShorts?.[Number(ss.dataset.shortShare)]?.text||'');return}});
addEventListener('click',e=>{const oc=e.target.closest('[data-official-category]');if(oc){renderOfficialHub(oc.dataset.officialCategory);document.getElementById('officialExamPanel')?.scrollIntoView({behavior:'smooth'});return}const oe=e.target.closest('[data-official-exam]');if(oe){state.selection.exam=oe.dataset.officialExam;state.selection.paperPost=postsFor(state.selection.exam)[0]||'';save();hydrate();document.getElementById('selectorPanel')?.scrollIntoView({behavior:'smooth'});return}const qe=e.target.closest('[data-quick-exam]');if(qe){state.selection.exam=qe.dataset.quickExam;state.selection.paperPost=postsFor(state.selection.exam)[0]||'';save();hydrate();syllabusBrowser();return}});
